import type { Meta, StoryObj } from '@storybook/react-webpack5';
import { ZimmInlineMessage } from '.';

/**
 * Six stories, deliberately overlapping variant+copy in places (per this build step's own
 * brief: "your call on exact story count/naming, as long as every one of the 3 exact strings and
 * both variants gets a real story") rather than inventing a fourth, non-canonical example string:
 * `Default`/`ErrorVariant`/`PartiallyOutOfStock` cover `error`; `Warning`/`MaxQuantityReached`
 * cover `warning` — every one of the three exact copy strings (SFCC-795 §11.2) appears at least
 * once, and both variants render at least once each.
 *
 * `Success` added SFCC-795 plan step 3.3 (2026-09-18) alongside the third variant itself — the
 * discount-label copy ("20% off applied") is the one real string this variant renders in
 * production (`product-item/index.tsx`'s `discountLabel` prop), so it's used verbatim here too.
 */
const meta: Meta<typeof ZimmInlineMessage> = {
  // Elements/, not Commerce/ — per components.md's own tiebreaker ("what does this component
  // know about?"): the prop surface is variant + text only, nothing product/cart/price-specific,
  // the same generic shape as Badge/Tag/Link. Its one caller today (ProductItem) is commerce
  // context, but that doesn't make the atom itself commerce-specific.
  title: 'Elements/ZimmInlineMessage',
  component: ZimmInlineMessage,
  parameters: { layout: 'padded' },
};

export default meta;
type Story = StoryObj<typeof ZimmInlineMessage>;

/** Fully out-of-stock — error variant, exact copy #1. */
export const Default: Story = {
  args: {
    variant: 'error',
    text: 'This item is unavailable',
  },
};

/** Named for the variant itself (`ErrorVariant`, not the bare `Error` identifier — that would
 *  shadow the built-in JS `Error` global within this module), distinct copy from `Default`
 *  (partial-OOS's string) so no two stories share identical args. */
export const ErrorVariant: Story = {
  args: {
    variant: 'error',
    text: 'Quantity unavailable in this size',
  },
};

/** Named `Warning` for the variant itself. Also the max-quantity copy — see zimmInlineMessage.css.ts
 *  for why this is `warning`, not `error`, despite the requirement text's own wording. */
export const Warning: Story = {
  args: {
    variant: 'warning',
    text: 'Maximum purchase quantity reached for this size',
  },
};

/** Partial OOS — error variant, exact copy #2. */
export const PartiallyOutOfStock: Story = {
  args: {
    variant: 'error',
    text: 'Quantity unavailable in this size',
  },
};

/** Max quantity reached — warning variant, exact copy #3. */
export const MaxQuantityReached: Story = {
  args: {
    variant: 'warning',
    text: 'Maximum purchase quantity reached for this size',
  },
};

/** Discount label — success variant, the real production copy (product-item/index.tsx's
 *  `discountLabel` prop). Green, regular weight, no icon — confirmed against Marcel's direct
 *  Figma inspector pull for this exact node (zimmInlineMessage.css.ts's own docblock). */
export const Success: Story = {
  args: {
    variant: 'success',
    text: '20% off applied',
  },
};

  // `.then(...)` on this callback's return value. A caller that omits this optional prop and
  // then changes quantity would throw. This default resolves to `true` (a valid change) so the
  // `.then` chain completes normally instead.
  onItemQuantityChange = async () => true,
  showLoading = false,
  containerStyles = {},
  isRemoving = false,
  pickupInStore = false,
  hideStepperAndActions = false,
  message,
  discountLabel,
}: ProductItemProps) => {
  const { stepQuantity, showInventoryMessage, inventoryMessage, quantity, setQuantity } = useDerivedProduct(
    product,
    false,
    false,
    pickupInStore,
  );
  const { currency: activeCurrency } = useCurrency();
  // hasError drives ZimmCartItem's own Item Details gap widening (12px -> 16px desktop) — see
  // product-item.css.ts's docblock — derived from `message`, not a separate prop, so the two can
  // never disagree about whether an error-variant message is currently showing.
  const styles = useMultiStyleConfig(ZIMM_CART_ITEM_RECIPE, { hasError: message?.variant === 'error' });
  return (
    <Box position="relative" data-testid={`sf-cart-item-${product.productId ? product.productId : product.id}`}>
      <ItemVariantProvider variant={product}>
        {showLoading && <LoadingSpinner />}
        <Stack layerStyle="cardBordered" align="flex-start" {...containerStyles}>
          <Flex sx={styles.row} width="full" backgroundColor="white">
            <CartItemVariantImage />
            <Stack sx={styles.details} flex={1}>
              <Flex sx={styles.info}>
                <Stack spacing={1}>
                  <CartItemVariantName />
                  <CartItemVariantAttributes excludeBonusLabel combineAttributeValues />
                  <HideOnDesktop>
                    <Box marginTop={2}>
                      <CartItemVariantPrice align="left" currency={activeCurrency} />
                    </Box>
                  </HideOnDesktop>
                </Stack>
                {!hideStepperAndActions && deliveryActions && !product.bonusProductLineItem && (
                  <HideOnMobile>{deliveryActions}</HideOnMobile>
                )}
              </Flex>

              {!hideStepperAndActions && deliveryActions && !product.bonusProductLineItem && (
                <HideOnDesktop>{deliveryActions}</HideOnDesktop>
              )}

              <Flex align="flex-end" justify="space-between">
                <Stack spacing={1}>
                  {!hideStepperAndActions &&
                    !(isRemoving && product.bonusProductLineItem) &&
                    (product.bonusProductLineItem ? (
                      <BonusProductQuantity product={product} />
                    ) : (
                      <ProductQuantityPicker
                        product={product}
                        onItemQuantityChange={onItemQuantityChange}
                        stepQuantity={stepQuantity}
                        quantity={quantity}
                        setQuantity={setQuantity}
                      />
                    ))}
                </Stack>
                <Stack>
                  <HideOnMobile>
                    <CartItemVariantPrice currency={activeCurrency} />
                  </HideOnMobile>
                  {!hideStepperAndActions && <HideOnMobile>{primaryAction}</HideOnMobile>}
                </Stack>
              </Flex>

              {/* SFCC-795 (plan step 3.3): discount label, directly beneath the stepper/price row
                  above, ahead of the inline message below — prop-driven only, no empty node when
                  omitted. See the `discountLabel` prop's own JSDoc for the styling citation. */}
              {discountLabel && (
                <ZimmInlineMessage variant="success" text={discountLabel} dataTestId="zimm-discount-label" />
              )}

              {/* SFCC-795 §11.2: sits between the stepper (above) and the actions row (the
                  existing inventory Box below, secondaryActions, and the mobile primaryAction
                  block further down) — prop-driven only, see this file's own docblock. */}
              {message && <ZimmInlineMessage variant={message.variant} text={message.text} />}

              <Box>
                {product && showInventoryMessage && (
                  <Fade in={true}>
                    <Text color="orange.600" fontWeight={600}>
                      {inventoryMessage}
                    </Text>
                  </Fade>
                )}
              </Box>

              {!hideStepperAndActions && secondaryActions}
            </Stack>
          </Flex>

          {!hideStepperAndActions && (
            <HideOnDesktop>
              <Box w={'full'}>{primaryAction}</Box>
            </HideOnDesktop>
          )}
        </Stack>
      </ItemVariantProvider>
    </Box>
  );
};

export default ProductItem;
